async () => {
const res = {};
const radios = [...document.querySelectorAll('form input[type=radio]')];
const lab = r => (r.getAttribute('aria-label') || r.closest('label')?.innerText || r.value).trim();
const colors = radios.filter(r => /blue|black|olive/i.test(lab(r)));
const sizeM = radios.find(r => lab(r) === 'M');
for (const c of colors) {
  if (c.disabled) { res[lab(c)] = 'color disabled'; continue; }
  c.click();
  await new Promise(r => setTimeout(r, 300));
  const m = [...document.querySelectorAll('form input[type=radio]')].find(r => lab(r) === 'M');
  res[lab(c)] = { mDisabled: m.disabled, aria: m.getAttribute('aria-label'), note: document.querySelector('form').innerText.replace(/\n+/g,' | ') };
}
return res;
}

